    FlowGraph(int n, int S, int T): adj(n), lv(n), it(n), s(S), t(T) {}
    void add_edge(int u, int v, int c) {
        int a = adj[v].size();
        int b = adj[u].size();
        adj[u].push_back({v, c, a});
        adj[v].push_back({u, 0, b});
    }
    bool bfs() {
        fill(lv.begin(), lv.end(), -1);
        lv[s] = 0;
        queue<int> q; q.push(s);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(auto &e: adj[u]) {
                if(lv[e.v] == -1 && e.w > 0) {
                    lv[e.v] = lv[u] + 1;
                    q.push(e.v);
                }
            }
        }
        return lv[t] != -1;
    }
    int dfs(int u, int f) {
        if(u == t) return f;
        for(int &i = it[u]; i < (int)adj[u].size(); ++i) {
            auto &e = adj[u][i];
            if(lv[e.v] == lv[u] + 1 && e.w > 0) {
                int ret = dfs(e.v, min(f, e.w));
                if(ret) {
                    e.w -= ret;
                    adj[e.v][e.rev].w += ret;
