import java.util.*;

public class Main {
    static int N, K;
    static String[] A = new String[15];
    static String[] B = new String[15];
    static int[][] D = new int[15][15];
    static int si, sj;
    static int[] moveX = {1, -1, 0, 0};
    static int[] moveY = {0, 0, 1, -1};

    static class Edge {
        int v, w, rev;
        Edge(int v, int w, int rev) {
            this.v = v;
            this.w = w;
            this.rev = rev;
        }
    }

    static class FlowGraph {
        ArrayList<ArrayList<Edge>> adj;
        int[] lv, it;
        int s, t;

        FlowGraph(int n, int S, int T) {
            adj = new ArrayList<>(n);
            for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
            lv = new int[n];
            it = new int[n];
            s = S;
            t = T;
        }

        void addEdge(int u, int v, int c) {
            int a = adj.get(v).size();
            int b = adj.get(u).size();
            adj.get(u).add(new Edge(v, c, a));
            adj.get(v).add(new Edge(u, 0, b));
        }

        boolean bfs() {
            Arrays.fill(lv, -1);
            lv[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : adj.get(u)) {
                    if (lv[e.v] == -1 && e.w > 0) {
                        lv[e.v] = lv[u] + 1;
                        q.add(e.v);
                    }
                }
            }
            return lv[t] != -1;
        }

        int dfs(int u, int f) {
            if (u == t) return f;
            for (int i = it[u]; i < adj.get(u).size(); i++) {
                it[u] = i;
                Edge e = adj.get(u).get(i);
                if (lv[e.v] == lv[u] + 1 && e.w > 0) {
                    int ret = dfs(e.v, Math.min(f, e.w));
                    if (ret > 0) {
                        e.w -= ret;
                        adj.get(e.v).get(e.rev).w += ret;
                        return ret;
                    }
                }
            }
            return 0;
        }

        long dinic() {
            long ans = 0;
            while (bfs()) {
                Arrays.fill(it, 0);
                int f;
                while ((f = dfs(s, 2000000000)) > 0) ans += f;
            }
            return ans;
        }
    }

    static void fillDist() {
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{si, sj});
        D[si][sj] = 1;
        int level = 1;
        while (!q.isEmpty()) {
            int sz = q.size();
            for (int z = 0; z < sz; z++) {
                int[] p = q.poll();
                for (int dir = 0; dir < 4; dir++) {
                    int ni = p[0] + moveX[dir];
                    int nj = p[1] + moveY[dir];
                    if (ni < 0 || ni >= N || nj < 0 || nj >= N) continue;
                    if (D[ni][nj] != 0 || A[ni].charAt(nj) == 'Y') continue;
                    D[ni][nj] = level;
                    q.add(new int[]{ni, nj});
                }
            }
            level++;
            level = Math.min(level, K);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        K = sc.nextInt();
        sc.nextLine(); // consume newline
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextLine();
            for (int j = 0; j < N; j++) {
                if (A[i].charAt(j) == 'Z') {
                    si = i;
                    sj = j;
                }
            }
        }
        // skip two lines (as in original code)
        sc.nextLine();
        sc.nextLine();
        for (int i = 0; i < N; i++) {
            B[i] = sc.nextLine();
        }

        fillDist();

        int cnt = 0;
        int[][][] id = new int[N][N][K + 2];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                char ca = A[i].charAt(j);
                if (ca >= '0' && ca <= '9') {
                    if (D[i][j] == 0) D[i][j] = K;
                    for (int t = 0; t < D[i][j]; t++) {
                        id[i][j][t] = ++cnt;
                    }
                }
                char cb = B[i].charAt(j);
                if (cb >= '1' && cb <= '9') {
                    id[i][j][D[i][j]] = ++cnt;
                }
            }
        }

        int INF = 1000000000;
        int S = 0, E = cnt + 3;
        FlowGraph fg = new FlowGraph(cnt + 5, S, E);

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                char ca = A[i].charAt(j);
                if (ca >= '1' && ca <= '9') {
                    fg.addEdge(S, id[i][j][0], ca - '0');
                }
                for (int d = 0; d < 4; d++) {
                    int ni = i + moveX[d];
                    int nj = j + moveY[d];
                    if (ni < 0 || ni >= N || nj < 0 || nj >= N) continue;
                    char na = A[ni].charAt(nj);
                    if (na == 'Y' || na == 'Z') continue;
                    for (int t = 0; ; t++) {
                        if (id[i][j][t] == 0) break;
                        if (t == D[i][j] && B[i].charAt(j) >= '1' && B[i].charAt(j) <= '9') break;
                        if (id[ni][nj][t + 1] != 0) {
                            fg.addEdge(id[i][j][t], id[ni][nj][t + 1], INF);
                        }
                    }
                }
                char cb = B[i].charAt(j);
                if (cb >= '1' && cb <= '9') {
                    for (int t = 0; t < D[i][j]; t++) {
                        fg.addEdge(id[i][j][t], id[i][j][t + 1], INF);
                    }
                    fg.addEdge(id[i][j][D[i][j]], E, cb - '0');
                }
            }
        }

        System.out.println(fg.dinic());
        sc.close();
    }
}
